import { Fragment, memo } from "react";
import clsx from "clsx";
import { Icon } from "../ui/icons.jsx";
import { Box, Item, Text } from "../ui/ds.jsx";

function Highlight({ text, query }) {
    if (!query || !text.toLowerCase().startsWith(query.toLowerCase()))
        return text;
    return (
        <>
            <strong className="font-bold">{text.slice(0, query.length)}</strong>
            {text.slice(query.length)}
        </>
    );
}

const Suggestion = memo(function Suggestion({ item, query, active, onPick }) {
    const icon = item.type === "article" ? "info" : item.type === "trend" ? "trend" : "search";
    return (
        <Item id={`suggestion-${item.id}`} role="option" aria-selected={active} className={clsx("flex cursor-pointer items-center gap-3 px-4 py-2 text-sm", active ? "bg-brand-50 text-brand-800" : "text-ink-800 hover:bg-ink-50")} onMouseDown={(event) => {
            event.preventDefault();
            onPick();
        }}>
            <Icon name={icon} size={16} className="text-ink-400" />
            <Text className="min-w-0 flex-1 truncate"><Highlight text={item.text} query={query} /></Text>
            {item.section ? <Text className="text-xs text-ink-500">{item.section}</Text> : null}
        </Item>
    );
});

export default function SuggestionList({ id, result, query, active, onPick }) {
    const queries = result.items.filter((item) => item.type !== "article");
    const articles = result.items.filter((item) => item.type === "article");
    return (
        <Box className="absolute top-full right-0 left-0 z-(--z-popover) mt-1 animate-fade-in overflow-hidden rounded-teaser border border-ink-200 bg-paper py-2 shadow-popover">
            <ul id={id} role="listbox" aria-label="Suchvorschläge">
                {result.kind === "zero" ? <Item role="presentation" className="px-4 pb-1 text-xs font-bold text-ink-500 uppercase">Gerade gesucht</Item> : null}
                {[queries, articles].map((group, g) => (
                    <Fragment key={g}>
                        {g === 1 && group.length ? <Item role="presentation" className="mt-1 border-t border-ink-100 px-4 pt-2 pb-1 text-xs font-bold text-ink-500 uppercase">Artikel</Item> : null}
                        {group.map((item) => <Suggestion key={item.id} item={item} query={query} active={result.items[active] === item} onPick={onPick} />)}
                    </Fragment>
                ))}
            </ul>
        </Box>
    );
}
